{%- assign hw_giftwrap_product = all_products['gift-wrap'] -%}
{%- assign hw_giftwrap_variant = hw_giftwrap_product.variants.first -%}

<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css" data-hw-fontawesome>

<div
  class="hw-card-addon-wrap"
  data-hw-giftwrap-addon
  data-variant-id="{{ hw_giftwrap_variant.id }}"
  data-price="{{ hw_giftwrap_variant.price | divided_by: 100.0 }}"
  data-items-index="8"
  data-gate-value="Zwart metalen houder"
>
  <label class="hw-card-addon-row">
    <span class="hw-card-addon-icon" aria-hidden="true">
      <i class="fa-solid fa-gift"></i>
    </span>

    <span class="hw-card-addon-text">
      <span class="hw-card-addon-title">Als een cadeautje inpakken.</span>
      <span class="hw-card-addon-price">+ {{ hw_giftwrap_variant.price | money }}</span>
    </span>

    <span class="hw-card-addon-switch">
      <input type="checkbox" data-hw-giftwrap-toggle>
      <span class="hw-card-addon-slider"></span>
    </span>
  </label>
</div>

<style>
  .hw-card-addon-wrap {
    font-family: inherit;
    font-size: 12px;
    font-weight: normal;
    color: #000000;
    border: 1px solid #D7D7D7;
    border-radius: 20px;
    background: #F6F6F6;
    padding: 5px 7px;
    margin: 0 0 0.5rem 0;
  }

  .hw-card-addon-row {
    display: flex;
    align-items: center;
    gap: 10px;
    cursor: pointer;
  }

  .hw-card-addon-icon {
    flex: 0 0 32px;
    width: 32px;
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 20px;
    color: #000000;
  }

  .hw-card-addon-text {
    flex: 1 1 auto;
    display: flex;
    flex-direction: column;
    gap: 2px;
    min-width: 0;
  }

  .hw-card-addon-title {
    font-size: 12px;
    font-weight: normal;
    color: #000000;
  }

  .hw-card-addon-price {
    font-size: 12px;
    font-weight: normal;
    color: #000000;
    opacity: 0.75;
  }

  .hw-card-addon-switch {
    flex: 0 0 auto;
    position: relative;
    width: 42px;
    height: 24px;
  }

  .hw-card-addon-switch input {
    opacity: 0;
    width: 0;
    height: 0;
  }

  .hw-card-addon-slider {
    position: absolute;
    inset: 0;
    background: #D7D7D7;
    border-radius: 999px;
    transition: background 0.15s ease;
  }

  .hw-card-addon-slider::before {
    content: "";
    position: absolute;
    width: 18px;
    height: 18px;
    left: 3px;
    top: 3px;
    background: #ffffff;
    border-radius: 50%;
    transition: transform 0.15s ease;
  }

  .hw-card-addon-switch input:checked + .hw-card-addon-slider {
    background: #000000;
  }

  .hw-card-addon-switch input:checked + .hw-card-addon-slider::before {
    transform: translateX(18px);
  }
</style>

<script>
(function () {
  function getWrap() {
    var all = document.querySelectorAll('[data-hw-giftwrap-addon]');
    return all.length ? all[all.length - 1] : null;
  }

  var wrap = getWrap();
  if (!wrap) return;

  var toggle = wrap.querySelector('[data-hw-giftwrap-toggle]');
  var variantId = wrap.dataset.variantId;
  var price = parseFloat(wrap.dataset.price || '0');
  var itemsIndex = wrap.dataset.itemsIndex || '8';
  var gateValue = wrap.dataset.gateValue || '';

  function parsePrice(text) {
    var clean = (text || '').replace(/[^\d,.-]/g, '').replace(/\.(?=\d{3}(,|$))/g, '').replace(',', '.');
    var n = parseFloat(clean);
    return isNaN(n) ? 0 : n;
  }

  function formatPrice(n) {
    try {
      return new Intl.NumberFormat('nl-NL', {
        style: 'currency',
        currency: '{{ cart.currency.iso_code | default: shop.currency }}'
      }).format(n);
    } catch (e) {
      return '€ ' + n.toFixed(2).replace('.', ',');
    }
  }

  // Zelfde delta-aanpak als bij het kaartje: werkt zowel de zijbalkprijs
  // als de prijs IN de "Toevoegen aan winkelmand"-knop bij.
  var priceApplied = false;
  function updatePrices() {
    var shouldApply = !!(toggle.checked);
    if (shouldApply === priceApplied) return;
    var delta = shouldApply ? price : -price;
    priceApplied = shouldApply;

    document.querySelectorAll('[data-js-product-price-original]').forEach(function (el) {
      el.textContent = formatPrice(parsePrice(el.textContent) + delta);
    });
    var btnPriceEl = document.querySelector('section-store--atc-price');
    if (btnPriceEl) {
      btnPriceEl.textContent = formatPrice(parsePrice(btnPriceEl.textContent) + delta);
    }
  }

  function getForms() {
    var forms = document.querySelectorAll('.product-form .form');
    if (forms.length) return forms;
    var fallback = document.querySelector('form[data-type="add-to-cart-form"]');
    return fallback ? [fallback] : [];
  }

  function removeFields() {
    getForms().forEach(function (form) {
      form.querySelectorAll('[data-hw-giftwrap-hidden]').forEach(function (el) { el.remove(); });
    });
  }

  function addFields() {
    removeFields();
    getForms().forEach(function (form) {
      var fields = {};
      fields['items[' + itemsIndex + '][id]'] = variantId;
      fields['items[' + itemsIndex + '][quantity]'] = '1';

      Object.keys(fields).forEach(function (name) {
        var input = document.createElement('input');
        input.type = 'hidden';
        input.name = name;
        input.id = variantId;
        input.value = fields[name];
        input.setAttribute('data-hw-giftwrap-hidden', '');
        form.appendChild(input);
      });
    });
  }

  function zetVelden() {
    if (toggle.checked) {
      addFields();
    } else {
      removeFields();
    }
  }

  // Zet de toggle geforceerd uit (en verwijdert regel + prijs) zonder dat
  // de klant er iets voor hoeft te doen — gebruikt bij het wisselen naar
  // de variant die niet ingepakt kan worden.
  function forceOff() {
    if (!toggle.checked) return;
    toggle.checked = false;
    updatePrices();
    zetVelden();
  }

  // Verbergt/toont dit blok op basis van de huidige "Houder"-keuze.
  //
  // LET OP: we zoeken NIET meer op een vaste select-id-prefix. Op
  // verschillende productpagina's heet deze optie net even anders
  // ("Houder", "Houder:", "Kies houder", ...), waardoor Shopify elke
  // keer een andere select-id genereert. In plaats daarvan zoeken we
  // gewoon de <select> op de pagina die zelf een keuze "Zwart metalen
  // houder" bevat — dat werkt ongeacht hoe de optie heet.
  var cachedGateSelect;
  function findGateSelect() {
    if (cachedGateSelect && document.body.contains(cachedGateSelect)) {
      return cachedGateSelect;
    }
    cachedGateSelect = null;
    if (!gateValue) return null;
    var selects = document.querySelectorAll('select');
    for (var i = 0; i < selects.length; i++) {
      var opts = selects[i].querySelectorAll('option');
      for (var j = 0; j < opts.length; j++) {
        var opt = opts[j];
        if (opt.value === gateValue || opt.textContent.trim() === gateValue) {
          cachedGateSelect = selects[i];
          return cachedGateSelect;
        }
      }
    }
    return null;
  }

  function applyGate() {
    var select = findGateSelect();
    if (!select) {
      wrap.hidden = false;
      return;
    }
    var blocked = select.value === gateValue;
    wrap.hidden = blocked;
    if (blocked) forceOff();
  }

  document.addEventListener('change', function (e) {
    var t = e.target.closest && e.target.closest('[data-hw-giftwrap-toggle]');
    if (t) {
      updatePrices();
      zetVelden();
      return;
    }
    // Reageer ook als de "Houder"-select zelf verandert.
    var select = findGateSelect();
    if (select && e.target === select) {
      applyGate();
    }
  });

  // Vangnet vlak voor de echte submit.
  document.addEventListener('submit', function (e) {
    var w = getWrap();
    if (!w || w.hidden) return;
    var t = w.querySelector('[data-hw-giftwrap-toggle]');
    if (!t || !t.checked) return;
    addFields();
  }, true);

  // Initiële staat bij laden van de pagina (bijv. als "Zwart metalen
  // houder" al vooraf geselecteerd stond).
  applyGate();
})();
</script>

