  }

  function formatPrice(n) {
    try {
      return new Intl.NumberFormat('nl-NL', {
        style: 'currency',
        currency: '{{ cart.currency.iso_code | default: shop.currency }}'
      }).format(n);
    } catch (e) {
      return '€ ' + n.toFixed(2).replace('.', ',');
    }
  }

  // Werkt zowel de prijs in de zijbalk ([data-js-product-price-original])
  // als de prijs IN de "Toevoegen aan winkelmand"-knop bij
  // (<section-store--atc-price>). Dat laatste element is precies waar
  // de echte Addons-app (cadeauverpakking) de knop-prijs laat zien, en
  // is een ander element dan de zijbalk-prijs — vandaar twee doelen.
  //
  // We werken met een delta (+prijs bij aanzetten, -prijs bij
  // uitzetten) in plaats van "base + addon" opnieuw te berekenen, zodat
  // dit correct blijft optellen als er ook een andere addon (zoals
  // cadeauverpakking) tegelijk aan staat — precies zoals die knop-prijs
  // ook bij de echte Addons-app werkt.
  var priceApplied = false;

  function updatePrices() {
    var shouldApply = !!(toggle.checked);
    if (shouldApply === priceApplied) return;
    var delta = shouldApply ? price : -price;
    priceApplied = shouldApply;

    document.querySelectorAll('[data-js-product-price-original]').forEach(function (el) {
      el.textContent = formatPrice(parsePrice(el.textContent) + delta);
    });
    var btnPriceEl = document.querySelector('section-store--atc-price');
    if (btnPriceEl) {
      btnPriceEl.textContent = formatPrice(parsePrice(btnPriceEl.textContent) + delta);
    }
  }

  function updateCharCount() {
    charCount.textContent = textarea.value.length + ' / 300';
  }

  // Exact dezelfde doel-elementen als de echte "SS - Product Addons"
  // sectie gebruikt: alle formulieren binnen .product-form .form.
  function getForms() {
    var forms = document.querySelectorAll('.product-form .form');
    if (forms.length) return forms;
    // Fallback voor thema's waar die klasse-combinatie niet voorkomt.
    var fallback = document.querySelector('form[data-type="add-to-cart-form"]');
    return fallback ? [fallback] : [];
  }

  function removeFields() {
    getForms().forEach(function (form) {
      form.querySelectorAll('[data-hw-card-hidden]').forEach(function (el) { el.remove(); });
    });
  }

  function addFields(message) {
    removeFields();
    getForms().forEach(function (form) {
      var fields = {};
      fields['items[' + itemsIndex + '][id]'] = variantId;
      fields['items[' + itemsIndex + '][quantity]'] = '1';
      fields['items[' + itemsIndex + '][properties][Boodschap voor kaartje]'] = message;

      Object.keys(fields).forEach(function (name) {
        var input = document.createElement('input');
        input.type = 'hidden';
        input.name = name;
        input.id = variantId;
        input.value = fields[name];
        input.setAttribute('data-hw-card-hidden', '');
        form.appendChild(input);
      });
    });
  }

  function zetVelden() {
    var msg = (textarea.value || '').trim();
    if (toggle.checked && msg) {
      addFields(msg);
    } else {
      removeFields();
    }
  }

  // Document-niveau delegatie: zelfde als hierboven uitgelegd, zodat dit
  // blijft werken ook als het thema de knoppen/variant-sectie vervangt.
  document.addEventListener('change', function (e) {
    var t = e.target.closest && e.target.closest('[data-hw-card-toggle]');
    if (!t) return;
    var w = t.closest('[data-hw-card-addon]');
    if (!w) return;
    var p = w.querySelector('[data-hw-card-message]');
    var err = w.querySelector('[data-hw-card-error]');
    var ta = w.querySelector('[data-hw-card-text]');
    if (p) p.hidden = !t.checked;
    if (t.checked) {
      if (ta) ta.focus();
      if (!ta || !ta.value.trim()) {
        if (err) err.hidden = false;
      } else if (err) {
        err.hidden = true;
      }
    } else if (err) {
      err.hidden = true;
    }
    updatePrices();
    zetVelden();
  });

  document.addEventListener('input', function (e) {
    var ta = e.target.closest && e.target.closest('[data-hw-card-text]');
    if (!ta) return;
    var w = ta.closest('[data-hw-card-addon]');
    if (!w) return;
    var err = w.querySelector('[data-hw-card-error]');
    updateCharCount();
    if (ta.value.trim() && err) err.hidden = true;
    zetVelden();
  });

  // Vangnet: ook net voor de submit zelf nog een keer controleren/zetten
  // (mocht de change/input-sync om wat voor reden dan ook gemist zijn).
  document.addEventListener('submit', function (e) {
    var w = getWrap();
    if (!w) return;
    var t = w.querySelector('[data-hw-card-toggle]');
    var ta = w.querySelector('[data-hw-card-text]');
    var err = w.querySelector('[data-hw-card-error]');
    if (!t || !t.checked) return;
    if (!ta || !ta.value.trim()) {
      e.preventDefault();
      removeFields();
      if (err) err.hidden = false;
      if (ta) ta.focus();
      return;
    }
    addFields(ta.value.trim());
  }, true);

  updateCharCount();
})();
</script>
